CELLS = [
"import torch\nfrom torch import nn\ntorch.manual_seed(0)\nn = 500\nf = lambda x: x ** 2 / 2            # 真实规律：一条抛物线\nx_src = torch.normal(-0.5, 0.6, size=(n, 1))   # 训练数据从这里来（源分布）\nx_tgt = torch.normal(1.0, 0.6, size=(n, 1))    # 实际使用时的数据（目标分布）\ny_src = f(x_src) + torch.normal(0, 0.1, size=(n, 1))\ny_tgt = f(x_tgt) + torch.normal(0, 0.1, size=(n, 1))\nx_src.mean(), x_tgt.mean()",
"def fit(weights):\n    net = nn.Linear(1, 1)\n    opt = torch.optim.SGD(net.parameters(), lr=0.1)\n    for epoch in range(300):\n        l = (weights * (net(x_src) - y_src) ** 2).sum() / weights.sum()\n        opt.zero_grad()\n        l.backward()\n        opt.step()\n    return net\n\ndef target_mse(net):\n    return ((net(x_tgt) - y_tgt) ** 2).mean().item()\n\nnet_plain = fit(torch.ones(n, 1))\nprint('不加权，目标分布上的 MSE：', round(target_mse(net_plain), 4))",
"X = torch.cat([x_src, x_tgt])\nz = torch.cat([torch.zeros(n, 1), torch.ones(n, 1)])   # 1 表示来自目标分布\nclf = nn.Linear(1, 1)\nopt = torch.optim.SGD(clf.parameters(), lr=0.5)\nbce = nn.BCEWithLogitsLoss()\nfor step in range(300):\n    l = bce(clf(X), z)\n    opt.zero_grad()\n    l.backward()\n    opt.step()\nbeta = torch.exp(clf(x_src)).detach().clamp(max=20)   # β(x) ≈ p_目标(x) / p_源(x)\nprint('β 的最小值、中位数、最大值：', beta.min().item() < 0.5, beta.max().item() > 5)\nnet_w = fit(beta)\nprint('加权后，目标分布上的 MSE：', target_mse(net_w) < target_mse(net_plain))",
]
